package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class RepresentationConversionsTest {
 private static Question q(String id,String raw){return new Question(id,RepresentationConversions.prompt(id,raw),"poison","999");}
 private static Checker.Result check(Question q,String value){return new Checker().check(q,List.of(),Collections.singletonList(value));}
 @Test public void allSixDirectionsPreserveTheExactValueAndRequireTheTargetRepresentation(){
  String[][] rows={{RepresentationConversions.FD,"1/5","0.2"},{RepresentationConversions.FP,"1/5","20%"},{RepresentationConversions.DF,"0.2","1/5"},{RepresentationConversions.DP,"0.2","20.0 %"},{RepresentationConversions.PF,"20%","1/5"},{RepresentationConversions.PD,"20%","0.2"}};
  for(String[] row:rows){Question q=q(row[0],row[1]);assertEquals(Rational.of(1,5),RepresentationConversions.read(q).value());assertTrue(row[0],check(q,row[2]).correct());assertFalse(row[0],check(q,"999").correct());assertFalse(HelpPlan.forQuestion(q).canTransfer());}
  assertEquals(Checker.Status.INPUT_NEEDED,check(q(RepresentationConversions.FD,"1/1"),"1").status);assertTrue(check(q(RepresentationConversions.FD,"1/1"),"1.0").correct());assertEquals(Checker.Status.INPUT_NEEDED,check(q(RepresentationConversions.FP,"1/5"),"20").status);assertEquals("백분율 기호 % 입력 필요",check(q(RepresentationConversions.FP,"1/5"),"20").message);assertEquals(Checker.Status.INPUT_NEEDED,check(q(RepresentationConversions.DF,"0.2"),"0.2").status);assertEquals(Checker.Status.WRONG_ANSWER,check(q(RepresentationConversions.DP,"0.2"),"0.2%").status);
 }
 @Test public void recurringAliasesZeroImproperAndDecimalPercentagesAreGeneralPublicMathematics(){
  String[][] rows={{RepresentationConversions.FD,"1/3","0.3(3)"},{RepresentationConversions.FP,"4/3","133.(3)%"},{RepresentationConversions.DF,"0.(33)","1/3"},{RepresentationConversions.DP,"0.1(6)","16.(6)%"},{RepresentationConversions.PF,"33.(3)%","1/3"},{RepresentationConversions.PD,"33.(3)%","0.(3)"},{RepresentationConversions.PF,"0.(3)%","1/300"},{RepresentationConversions.PD,"0.(3)%","0.00(3)"},{RepresentationConversions.DF,"0.(9)","1/1"},{RepresentationConversions.DP,"0.(9)","100%"},{RepresentationConversions.PF,"150.50%","301/200"},{RepresentationConversions.PD,"150.50%","1.505"},{RepresentationConversions.DF,"3.5","7/2"},{RepresentationConversions.DP,"3.5","350%"},{RepresentationConversions.PF,"0%","0/1"}};
  for(String[] row:rows){Question q=q(row[0],row[1]);assertNotNull(row[0]+row[1],RepresentationConversions.read(q));assertTrue(row[0]+row[1],check(q,row[2]).correct());assertTrue(CurriculumLimits.NONE.allows(q));assertNotNull(HelpPlan.forQuestion(q));}
  assertFalse(check(q(RepresentationConversions.FD,"1/3"),"0.333").correct());assertFalse(check(q(RepresentationConversions.FP,"1/3"),"33.333%").correct());Question raw=q(RepresentationConversions.DF,"00012.3400");assertEquals("00012.3400",RepresentationConversions.read(raw).raw());assertTrue(check(raw,"617/50").correct());assertEquals("006/012",RepresentationConversions.read(q(RepresentationConversions.FD,"006/012")).raw());
 }
 @Test public void simplestFractionIsAFormatRequirementAndOnlyUniqueTargetPartsAreBlamed(){
  Question q=q(RepresentationConversions.DF,"0.50");Checker.Result unreduced=check(q,"2/4");assertEquals(Checker.Status.INPUT_NEEDED,unreduced.status);assertEquals("약분 필요",unreduced.message);assertEquals(Checker.InputTarget.ANSWER,unreduced.inputTarget);assertFalse(unreduced.mathematicalError());assertEquals(0,unreduced.index);assertTrue(check(q,"01/02").correct());assertEquals(Checker.Status.WRONG_ANSWER,check(q,"1/4").status);assertEquals(2,RepresentationConversions.errorPart(q,"1/4"));assertEquals(1,RepresentationConversions.errorPart(q,"2/2"));assertEquals(0,RepresentationConversions.errorPart(q,"2/4"));assertEquals(0,RepresentationConversions.errorPart(q,"2/3"));assertEquals(0,RepresentationConversions.errorPart(q,"1/2"));assertEquals(2,FractionInput.errorPart(q,"1/4"));assertEquals(1,FractionInput.errorPart(q,"2/2"));assertEquals(Checker.Status.INPUT_NEEDED,check(q,"1/0").status);
  assertTrue(check(q(RepresentationConversions.DF,"2.0"),"2/1").correct());assertTrue(check(q(RepresentationConversions.PF,"0%"),"0/1").correct());assertEquals(Checker.Status.INPUT_NEEDED,check(q(RepresentationConversions.PF,"0%"),"0/100").status);
 }
 @Test public void readonlyPublicGuideUsesRelationsScaleGcdAndManualFractionFramesWithoutStoredAuthority(){
  Question q=q(RepresentationConversions.DF,"0.50");q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide stored=q.studyGuide;StudyGuide g=RepresentationConversions.guide(q);HelpPlan h=HelpPlan.forQuestion(q);assertEquals(8,h.size());assertEquals(RepresentationConversions.VERSION,g.teachingVersion);assertEquals(Integer.valueOf(6),g.resultNumeratorFrame);assertEquals(Integer.valueOf(7),g.resultDenominatorFrame);assertEquals("100",g.frames.get(2).expected);assertEquals("50",g.frames.get(3).expected);assertEquals("100",g.frames.get(4).expected);assertEquals("50",g.frames.get(5).expected);assertEquals("1",g.frames.get(6).expected);assertEquals("2",g.frames.get(7).expected);assertFalse(h.canTransfer());
  List<String> entries=List.of("finiteFraction","0.50","100","50","100","50","1","2");for(int i=0;i<h.size();i++){assertTrue(i+":"+entries.get(i),h.step(i).accepts(entries.get(i)));assertEquals("",h.step(i).after);assertFalse(h.step(i).accepts(""));}HelpPlan.Draft draft=h.restore(null,q.id);assertEquals(List.of(""),draft.entries);draft.entries=new ArrayList<>(entries);draft.stage=8;assertEquals(8,h.restore(draft.copy(),q.id).stage);assertEquals("1/2",h.enteredAnswer(draft));assertSame(stored,q.studyGuide);assertEquals("poison",q.expression);assertArrayEquals(new String[]{"999"},q.answers);
  q.expression=null;q.answers=null;q.stepSupport=true;q.calculationMethod="written";assertTrue(new Checker().check(q,List.of("999=999"),List.of("1/2"),List.of(Checker.StepKind.FULL)).correct());assertEquals(8,HelpPlan.forQuestion(q).size());assertSame(stored,q.studyGuide);assertNull(q.expression);assertNull(q.answers);
  StudyGuide cycle=RepresentationConversions.guide(q(RepresentationConversions.DF,"0.1(6)"));assertEquals(9,cycle.frames.size());assertEquals("10",cycle.frames.get(2).expected);assertEquals("9",cycle.frames.get(3).expected);assertEquals("15",cycle.frames.get(4).expected);assertEquals("90",cycle.frames.get(5).expected);assertEquals("15",cycle.frames.get(6).expected);assertEquals("1",cycle.frames.get(7).expected);assertEquals("6",cycle.frames.get(8).expected);
 }
 @Test public void referencesExposeOnlyCheckedLearnerDependenciesAndNeverCalculatedTargets(){
  Question q=q(RepresentationConversions.DF,"0.50");List<String> entries=List.of("finiteFraction","0.500","0100","50","100","50");assertEquals(Map.of("분자 N = 0.50 × A = ","50","최대공약수 G = gcd(N, D) = ","50"),RepresentationConversions.references(q,6,entries));assertEquals(Map.of("분모 D = A = ","100","최대공약수 G = gcd(N, D) = ","50"),RepresentationConversions.references(q,7,entries));assertEquals(Map.of(),RepresentationConversions.references(q,6,List.of("finiteFraction","0.500","100","500","100","5")));assertEquals(Map.of(),RepresentationConversions.references(q,0,entries));assertEquals(Map.of(),RepresentationConversions.references(q,8,entries));assertEquals(Map.of(),RepresentationConversions.references(null,6,entries));
 }
 @Test public void largeOriginalsAndConvertedFractionComponentsStayReachableWithDedicatedInputs(){
  String raw="99999999999999999999.123456789012(34567890123456789013)";Question q=q(RepresentationConversions.DF,raw);var g=RepresentationConversions.read(q);assertNotNull(g);assertTrue(g.value().n.toString().length()>30);String expected=g.value().n+"/"+g.value().d;assertTrue(expected.length()<=120);assertTrue(check(q,expected).correct());HelpPlan h=HelpPlan.forQuestion(q);StudyGuide guide=RepresentationConversions.guide(q);HelpPlan.Draft draft=h.restore(null,q.id);List<String> entries=new ArrayList<>();for(StudyGuide.Frame f:guide.frames){String input=f.options.isEmpty()?f.inputFormat.equals("convDecimal")?raw:f.expected:f.expected;assertTrue(new HelpPlan.Step(f).accepts(input));entries.add(input);}draft.entries=entries;draft.stage=entries.size();assertEquals(expected,h.enteredAnswer(draft));
  Question finite=q(RepresentationConversions.FD,"1/73786976294838206464");String decimal=RepresentationConversions.read(finite).value().decimalText();assertTrue(check(finite,decimal).correct());assertTrue(HelpPlan.forQuestion(finite).step(3).accepts(decimal));assertEquals("1/99999999999999999989",RepresentationConversions.guide(q(RepresentationConversions.FD,"1/99999999999999999989")).frames.get(3).expected);
  try{Expression.number(g.value().n.toString());fail("Shared30-character number guard widened");}catch(IllegalArgumentException expectedGuard){}try{Rational.decimal("0."+"1".repeat(13));fail("Shared12-place guard widened");}catch(IllegalArgumentException expectedGuard){}
 }
 @Test public void malformedSourcesAndAnswerGuardsCannotFallBackToPrivateKeysOrGuides(){
  for(String[] row:List.of(new String[]{RepresentationConversions.FD,"1/0"},new String[]{RepresentationConversions.FD,"1".repeat(21)+"/2"},new String[]{RepresentationConversions.DF,"-0.5"},new String[]{RepresentationConversions.DF,"0."+"1".repeat(13)},new String[]{RepresentationConversions.DF,"0.("+"1".repeat(21)+")"},new String[]{RepresentationConversions.DF,"1e2"},new String[]{RepresentationConversions.PF,"35"},new String[]{RepresentationConversions.PF,"35‰"},new String[]{RepresentationConversions.PF,"(35)%"})){Question q=q(row[0],row[1]);q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide stored=q.studyGuide;assertNull(row[1],RepresentationConversions.read(q));assertNull(HelpPlan.forQuestion(q));assertSame(stored,q.studyGuide);assertEquals(Checker.Status.INPUT_NEEDED,check(q,"999").status);assertFalse(CurriculumLimits.NONE.allows(q));}
  for(String raw:List.of("0."+"0".repeat(119),"1e2","1/2","0,5","0.5+0",".5","1.","0.()",BigInteger.ONE.shiftLeft(512)+".0"))assertNull(raw,RepresentationConversions.decimalInput(raw));for(String raw:List.of("1/2%","1e2%","35‰","35%%","35％","0.5+0%","35"))assertNull(raw,RepresentationConversions.percentInput(raw));assertNull(RepresentationConversions.integerInput("1".repeat(121)));assertNull(RepresentationConversions.read(null));assertNull(RepresentationConversions.guide(null));assertFalse(RepresentationConversions.supports(null));assertFalse(RepresentationConversions.acceptsStep("1","1",null));Question extra=q(RepresentationConversions.FD,"1/2");extra.prompt+=" extra";assertNull(RepresentationConversions.read(extra));
 }
}
